/* The trace format stategate-view replays. Write the header once, then one
 * record per transition (the HAL's trace hook gives you from, event and to),
 * over any transport: a file, UART, BLE. The viewer refuses a log whose model
 * hash is not the model it has open. */
#ifndef LOGGER_TRACE_H
#define LOGGER_TRACE_H

#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* sha-256 of logger.yaml, the model this code was generated from. */
static const uint8_t logger_model_hash[32] = {0x9d, 0x6f, 0xd2, 0x4c, 0x45, 0x46, 0x8c, 0x3d, 0xaf, 0x97, 0x88, 0xc5, 0x76, 0xb9, 0x08, 0x74, 0x2a, 0xab, 0xae, 0xab, 0xd7, 0xd1, 0x02, 0xd9, 0xfd, 0xde, 0x96, 0xea, 0xd6, 0xd2, 0x0b, 0x60};

/* Appends one machine's entry to a header: id length, id, model hash. */
static inline size_t logger_trace_header_entry(uint8_t *out) {
    size_t n = strlen("logger");
    out[0] = (uint8_t)n;
    memcpy(out + 1, "logger", n);
    memcpy(out + 1 + n, logger_model_hash, 32);
    return 1 + n + 32;
}

/* The header of a log from this machine alone. out needs 44 bytes. */
static inline size_t logger_trace_header(uint8_t *out) {
    memcpy(out, "SGT1", 4);
    out[4] = 1;
    return 5 + logger_trace_header_entry(out + 5);
}

/* Shared by every machine's trace.h, so a system can include them all. */
#ifndef SG_TRACE_RECORD_SIZE
#define SG_TRACE_RECORD_SIZE 11

static inline void sg_trace_record(uint8_t out[SG_TRACE_RECORD_SIZE], uint32_t t_ms, uint16_t seq, uint8_t machine,
                                   uint8_t instance, uint8_t from, uint8_t event, uint8_t to) {
    out[0] = (uint8_t)t_ms;
    out[1] = (uint8_t)(t_ms >> 8);
    out[2] = (uint8_t)(t_ms >> 16);
    out[3] = (uint8_t)(t_ms >> 24);
    out[4] = (uint8_t)seq;
    out[5] = (uint8_t)(seq >> 8);
    out[6] = machine;
    out[7] = instance;
    out[8] = from;
    out[9] = event;
    out[10] = to;
}
#endif

#endif
